recipes.code:
{
  "inputs": [
    {
      "id": "aicommander-token",
      "type": "promptString",
      "description": "Account API key (or OAuth access token) for the optional accounts/alias features — saved machines, aliases, account access. Generate one for free at aicommander.dev.",
      "password": true
    }
  ],
  "servers": {
    "mcp": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "@aicommander/mcp@1.0.17"
      ],
      "env": {
        "AICOMMANDER_TOKEN": "${input:aicommander-token}",
        "AICOMMANDER_SERVER": "https://aicommander.dev"
      }
    }
  }
}
